package ca.mcgill.ecse321.ecse321project03.repository;

import org.springframework.data.repository.CrudRepository;

import ca.mcgill.ecse321.ecse321project03.model.Employee;

public interface EmployeeRepository extends CrudRepository<Employee, Integer> {

    /**
     * Find an employee by its associated account ID. Auto-generated by Spring Data JPA from method name.
     */
    Employee findByAccount_Id(int accountId);

}
